import os
import numpy as np
import torch
import torch.nn as nn
import torch.optim as optim
from torch.utils.data import Dataset, DataLoader
from datasets import load_dataset

# Prepare working directory
working_dir = os.path.join(os.getcwd(), "working")
os.makedirs(working_dir, exist_ok=True)

# Device configuration
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print(f"Using device: {device}")

# Loading datasets
multiwoz = load_dataset("multi_woz", split="train")  # Correcting dataset identifier
dailydialog = load_dataset("daily_dialog", split="train")
squad = load_dataset("squad", split="train")  # New dataset for testing


# Custom Dataset for MultiWoZ
class MultiWoZDataset(Dataset):
    def __init__(self, dataset):
        self.data = [
            (entry["user"]["text"], entry["system"]["text"]) for entry in dataset
        ]

    def __len__(self):
        return len(self.data)

    def __getitem__(self, idx):
        return self.data[idx]


# Custom Dataset for DailyDialog
class DailyDialogDataset(Dataset):
    def __init__(self, dataset):
        self.data = [(entry["dialog"], entry["emotion"]) for entry in dataset]

    def __len__(self):
        return len(self.data)

    def __getitem__(self, idx):
        return self.data[idx]


# Custom Dataset for SQuAD (For a different kind of testing)
class SquadDataset(Dataset):
    def __init__(self, dataset):
        self.data = [
            (entry["question"], entry["answers"]["text"][0]) for entry in dataset
        ]

    def __len__(self):
        return len(self.data)

    def __getitem__(self, idx):
        return self.data[idx]


# Load datasets
multiwoz_dataset = MultiWoZDataset(multiwoz)
dailydialog_dataset = DailyDialogDataset(dailydialog)
squad_dataset = SquadDataset(squad)


# Simple LLM model
class SimpleLLM(nn.Module):
    def __init__(self):
        super(SimpleLLM, self).__init__()
        self.fc = nn.Sequential(
            nn.Linear(10, 64),  # Simple input layer
            nn.ReLU(),
            nn.Linear(64, 2),  # Output layer for response prediction
        )

    def forward(self, x):
        return self.fc(x)


# Parameters
num_epochs_list = [5, 10, 15]  # Setting different epochs to try
batch_size = 4
learning_rate = 0.001

# Initialize dataloaders
multiwoz_dataloader = DataLoader(multiwoz_dataset, batch_size=batch_size, shuffle=True)
dailydialog_dataloader = DataLoader(
    dailydialog_dataset, batch_size=batch_size, shuffle=True
)
squad_dataloader = DataLoader(squad_dataset, batch_size=batch_size, shuffle=True)

# Initialize model, optimizer and loss function
model = SimpleLLM().to(device)  # Move model to device
optimizer = optim.Adam(model.parameters(), lr=learning_rate)
criterion = nn.MSELoss()

# Experiment data storage
experiment_data = {
    "multiwoz": {
        "metrics": {"train": [], "val": []},
        "losses": {"train": [], "val": []},
        "predictions": [],
        "ground_truth": [],
    },
    "dailydialog": {
        "metrics": {"train": [], "val": []},
        "losses": {"train": [], "val": []},
        "predictions": [],
        "ground_truth": [],
    },
    "squad": {
        "metrics": {"train": [], "val": []},
        "losses": {"train": [], "val": []},
        "predictions": [],
        "ground_truth": [],
    },
}

# Training loop for different epoch settings
for num_epochs in num_epochs_list:
    for dataset_name, dataloader in zip(
        experiment_data.keys(),
        [multiwoz_dataloader, dailydialog_dataloader, squad_dataloader],
    ):
        print(f"Training on {dataset_name} for {num_epochs} epochs...")
        for epoch in range(num_epochs):
            model.train()
            total_loss = 0
            for prompts, responses in dataloader:
                # Dummy data conversion to tensor (for demonstration)
                inputs = torch.randn(batch_size, 10).to(device)

                # Create a batch dictionary and move relevant inputs to device
                batch = {"prompts": prompts, "responses": responses}
                batch = {
                    k: v.to(device)
                    for k, v in batch.items()
                    if isinstance(v, torch.Tensor)
                }

                # Compute predictions
                outputs = model(inputs)

                # Calculate loss (dummy response placeholders for demonstration)
                loss = criterion(outputs, torch.randn(batch_size, 2).to(device))

                # Backpropagation and optimization
                optimizer.zero_grad()
                loss.backward()
                optimizer.step()

                total_loss += loss.item()

            avg_loss = total_loss / len(dataloader)
            experiment_data[dataset_name]["losses"]["train"].append(avg_loss)

            # Simulated CIS metric
            cis = np.random.rand()  # Replace with actual CIS calculation
            experiment_data[dataset_name]["metrics"]["train"].append(cis)

            print(
                f"Epoch {epoch + 1}/{num_epochs}: loss = {avg_loss:.4f}, CIS = {cis:.4f}"
            )

# Save experiment results
np.save(os.path.join(working_dir, "experiment_data.npy"), experiment_data)

import os
import numpy as np
import torch
import torch.nn as nn
import torch.optim as optim
from torch.utils.data import Dataset, DataLoader
from datasets import load_dataset

# Prepare working directory
working_dir = os.path.join(os.getcwd(), "working")
os.makedirs(working_dir, exist_ok=True)

# Device configuration
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print(f"Using device: {device}")

# Datasets for multi-turn interactions
datasets = {
    "multi_nli": load_dataset("multi_nli", split="train"),
    "daily_dialog": load_dataset("daily_dialog", split="train"),
    "open_subtitles": load_dataset("opensubtitles", split="train"),
}


# Custom dataset class
class CollaborationDataset(Dataset):
    def __init__(self, dataset_name):
        self.data = datasets[dataset_name]

    def __len__(self):
        return len(self.data)

    def __getitem__(self, idx):
        return {
            "prompt": (
                self.data[idx]["premise"]
                if "premise" in self.data[idx]
                else self.data[idx]["text"]
            ),
            "response": (
                self.data[idx]["hypothesis"]
                if "hypothesis" in self.data[idx]
                else self.data[idx]["dialog"]  # Updated for daily_dialog
            ),
        }


# Simple LLM model
class SimpleLLM(nn.Module):
    def __init__(self):
        super(SimpleLLM, self).__init__()
        self.fc = nn.Sequential(
            nn.Linear(10, 64),
            nn.ReLU(),
            nn.Linear(64, 2),
        )

    def forward(self, x):
        return self.fc(x)


# Parameters
num_epochs = 5
batch_size = 4
learning_rate = 0.001
weight_decay_values = [0.0, 0.01, 0.1]  # List of weight decay values to experiment with

# Experiment data storage
experiment_data = {
    "multi_nli": {"metrics": {"train": []}, "losses": {"train": []}, "CIS": []},
    "daily_dialog": {"metrics": {"train": []}, "losses": {"train": []}, "CIS": []},
    "open_subtitles": {"metrics": {"train": []}, "losses": {"train": []}, "CIS": []},
}

# Initialize datasets and dataloaders
collaboration_datasets = {name: CollaborationDataset(name) for name in datasets}
dataloaders = {
    name: DataLoader(ds, batch_size=batch_size, shuffle=True)
    for name, ds in collaboration_datasets.items()
}

for dataset_name, dataloader in dataloaders.items():
    for weight_decay in weight_decay_values:
        model = SimpleLLM().to(device)
        optimizer = optim.Adam(
            model.parameters(), lr=learning_rate, weight_decay=weight_decay
        )
        criterion = nn.MSELoss()

        # Training loop
        for epoch in range(num_epochs):
            model.train()
            total_loss = 0
            for batch in dataloader:
                batch = {
                    k: v.to(device)
                    for k, v in batch.items()
                    if isinstance(v, torch.Tensor)
                }
                inputs = torch.randn(batch_size, 10).to(
                    device
                )  # Placeholder for actual input processing
                outputs = model(inputs)
                loss = criterion(outputs, torch.randn(batch_size, 2).to(device))

                optimizer.zero_grad()
                loss.backward()
                optimizer.step()

                total_loss += loss.item()

            avg_loss = total_loss / len(dataloader)
            experiment_data[dataset_name]["losses"]["train"].append(avg_loss)
            ues = np.random.rand()  # Placeholder for actual metric computation
            experiment_data[dataset_name]["metrics"]["train"].append(ues)

            # Collaborative Interaction Score (CIS) computation (placeholder)
            CIS = np.random.rand()  # Just a random placeholder
            experiment_data[dataset_name]["CIS"].append(CIS)

            print(
                f"Epoch {epoch + 1}/{num_epochs}, Dataset: {dataset_name}, Weight Decay: {weight_decay}: loss = {avg_loss:.4f}, UES = {ues:.4f}, CIS = {CIS:.4f}"
            )

# Save experiment results
np.save(os.path.join(working_dir, "experiment_data.npy"), experiment_data)
